typedef unsigned int gid_t; // Represented by gid_t type

// Querying GIDs
gid_t real_gid = getgid();
gid_t eff_gid = getegid();

// Setting GIDs (Requires privileges/capabilities)
// Set effective GID only (Real unchanged)
int status1 = setegid(1001);

// Set real (R) and effective (E) GIDs
// -1 means keep current value
// Sets R=1000, E=2000
int status2 = setregid(1000, 2000);

// Querying all three GIDs (Real, Effective, Saved Set)
gid_t r, e, s;
int status3 = getresgid(&r, &e, &s);
